const fs = require('fs');
const path = require('path');

// ==== EDIT THESE FOR YOUR MACHINE ====
const BASE_DIR = process.env.AI_SHORTS_BASE_DIR || '/Users/tuht1/ai-shorts-videos';
const VIETTTS_URL = process.env.VIETTTS_URL || 'http://127.0.0.1:8002/tts';
const NICHE = ['Artificial Intelligence','Automation','Software','Programming',
  'AI Tools','Productivity','Tech News','LLMs','Open Source AI'];
const PLATFORMS = ['tiktok','youtube_shorts','facebook_reels'];
// =======================================

fs.mkdirSync(BASE_DIR, { recursive: true });
fs.mkdirSync(path.join(BASE_DIR, 'assets', 'bgm'), { recursive: true });
fs.mkdirSync(path.join(BASE_DIR, 'assets', 'sfx'), { recursive: true });
fs.mkdirSync(path.join(BASE_DIR, 'analytics'), { recursive: true });

// Module 11 (Analytics) writes this file; Module 1 reads it so today's
// research is informed by what actually performed well recently.
const learningsPath = path.join(BASE_DIR, 'analytics', 'learnings.json');
let learnings = { topPerformingTopics: [], topPerformingHooks: [], avoid: [] };
try {
  if (fs.existsSync(learningsPath)) learnings = JSON.parse(fs.readFileSync(learningsPath, 'utf8'));
} catch (e) { /* first run, no learnings yet */ }

const now = new Date();
return [{
  json: {
    BASE_DIR, VIETTTS_URL, NICHE, PLATFORMS, learnings,
    today: now.toISOString().slice(0, 10)
  }
}];

// One well-scoped Tavily query covering every requested source, rather than
// letting an agent decide (unreliable with small local models - see sticky note).
const niche = ($json.NICHE || []).join(', ');
const query = 'Trending in the last 3 days about ' + niche + ': '
  + 'Google Trends breakout topics, Google News headlines, popular YouTube videos, '
  + 'top Reddit discussions, GitHub Trending repositories, Product Hunt launches, '
  + 'and official OpenAI, Anthropic, Google AI blog announcements.';
return [{ json: { ...$json, trendQuery: query } }];

const prev = $('Build Trend Search Query').first().json;
const results = $json.results || [];
const digest = results.slice(0, 10).map((r, i) =>
  (i + 1) + '. ' + r.title + '\n   URL: ' + r.url + '\n   ' + (r.content || '').slice(0, 300)
).join('\n\n');

return [{ json: { ...prev, trendSearchDigest: digest || 'Khong co ket qua tim kiem.' } }];

