function parseAgentJson(raw) {
  if (typeof raw !== 'string') return raw;
  let t = raw.trim();
  const fence = t.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fence) t = fence[1];
  if (!/^[\{\[]/.test(t.trim())) {
    const m = t.match(/\{[\s\S]*\}/);
    if (m) t = m[0];
  }
  return JSON.parse(t);
}

let data;
try {
  data = parseAgentJson($json.output);
} catch (e) {
  throw new Error('Trend Synthesis Agent khong tra ve JSON hop le: ' + String($json.output).slice(0, 300));
}

if (!data.candidates || !Array.isArray(data.candidates) || data.candidates.length === 0) {
  throw new Error('Trend Synthesis Agent thieu field candidates[]');
}
if (data.candidates.length > 5) data.candidates = data.candidates.slice(0, 5);

const ranked = data.candidates.slice().sort((a, b) => (b.total_score || 0) - (a.total_score || 0));
const top = data.selected_topic && data.selected_topic.topic ? data.selected_topic : ranked[0];

const cfg = $('Load Config & Learnings').first().json;
return [{
  json: {
    ...cfg,
    candidates: ranked,
    topic: top.topic,
    whyNow: top.why_now,
    topicSourceUrls: top.source_urls || []
  }
}];

const prev = $('Build Deep Research Query').first().json;
const results = $json.results || [];
const digest = results.slice(0, 10).map((r, i) =>
  (i + 1) + '. ' + r.title + '\n   URL: ' + r.url + '\n   ' + (r.content || '').slice(0, 400)
).join('\n\n');

return [{ json: { ...prev, deepSearchDigest: digest || 'Khong co ket qua tim kiem.' } }];

