function parseAgentJson(raw) {
  if (typeof raw !== 'string') return raw;
  let t = raw.trim();
  const fence = t.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fence) t = fence[1];
  if (!/^[\{\[]/.test(t.trim())) {
    const m = t.match(/\{[\s\S]*\}/);
    if (m) t = m[0];
  }
  return JSON.parse(t);
}

let data;
try {
  data = parseAgentJson($json.output);
} catch (e) {
  throw new Error('Visual Director Agent khong tra ve JSON hop le.');
}

return [{
  json: {
    ...$json,
    scene: {
      ...$json.scene,
      eventQuery: data.event_query || $json.scene.visual_description,
      stockQuery: data.stock_query || 'technology abstract background'
    }
  }
}];

const path = require('path');
const fs = require('fs');

const BASE_DIR = $json.BASE_DIR;
const now = new Date();
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
const slug = String($json.topic || 'video')
  .toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 40);

// videoId is stable across all items of the same execution (based on execution id)
const videoId = $json.videoId || (dateStr + '-' + slug + '-' + $execution.id);
const videoDir = path.join(BASE_DIR, videoId);
const scenesDir = path.join(videoDir, 'scenes');
fs.mkdirSync(scenesDir, { recursive: true });

return { json: { ...$json, videoId, videoDir, scenesDir } };

// Splits this scene's subtitle text into short, readable phrases (max 2 lines
// worth each), spread proportionally across the REAL measured audio duration
// (from ffprobe), and flags 1-2 'keywords' per phrase to highlight later.
const ctx = $json; // this item already carries scene + paths from the loop

const durationSec = parseFloat($('Probe Voice Duration (ffprobe)').first().json.stdout.trim()) || ctx.scene.duration;

const text = String(ctx.scene.subtitle || ctx.scene.narration || '').trim();
// Split into clause-like chunks on punctuation, then re-group into <= 6-word phrases.
const rawParts = text.split(/(?<=[.,!?;:])\s+|\s{2,}/).filter(Boolean);
let words = [];
(rawParts.length ? rawParts : [text]).forEach(p => words.push(...p.split(/\s+/).filter(Boolean)));

const phrases = [];
let cur = [];
for (const w of words) {
  cur.push(w);
  if (cur.length >= 5) { phrases.push(cur.join(' ')); cur = []; }
}
if (cur.length) phrases.push(cur.join(' '));
if (phrases.length === 0) phrases.push(text || '...');

const perCue = durationSec / phrases.length;
const STOPWORDS = new Set(['la','va','cua','o','trong','mot','nhung','de','cho','khi','the','nay','voi','tu','duoc']);

function stripDiacritics(s) {
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\u0111/g, 'd').replace(/\u0110/g, 'D').toLowerCase();
}

const cues = phrases.map((p, i) => {
  const tokens = p.split(/\s+/);
  const keyword = tokens
    .filter(t => !STOPWORDS.has(stripDiacritics(t.replace(/[^\p{L}\p{N}]/gu, ''))))
    .sort((a, b) => b.length - a.length)[0] || tokens[0];
  return {
    start: +(i * perCue).toFixed(2),
    end: +((i + 1) * perCue).toFixed(2),
    text: p,
    keyword
  };
});

return [{
  json: {
    ...ctx,
    scene: { ...ctx.scene, measuredDuration: durationSec, subtitleCues: cues },
    audioPath: $('Write Scene Voice File').first().json.fileName
  }
}];

const bad = (url) => {
  if (!url) return true;
  url = url.toLowerCase();
  return (
    url.endsWith('.svg') || url.includes('.svg?') || url.includes('logo') ||
    url.includes('icon') || url.includes('favicon') ||
    url.includes('lookaside.instagram') || url.includes('instagram.com')
  );
};

let imageUrl = null;
if (Array.isArray($json.results)) {
  for (const result of $json.results) {
    if (!Array.isArray(result.images)) continue;
    imageUrl = result.images.find(u => !bad(u));
    if (imageUrl) break;
  }
}
if (!imageUrl && Array.isArray($json.images)) {
  imageUrl = $json.images.find(u => !bad(u));
}

const ctx = $('Build Scene Subtitle Cues').first().json;
return [{ json: { ...ctx, hasTavilyImage: !!imageUrl, tavilyImageUrl: imageUrl } }];

const scene = $input.item.json;
const binary = $input.item.binary && $input.item.binary.data;
let isValid = false;

if (binary) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  const isJpeg = buffer.length > 4 && buffer[0] === 0xFF && buffer[1] === 0xD8;
  const isPng = buffer.length > 8 && buffer[0] === 0x89 && buffer[1] === 0x50;
  const isWebp = buffer.length > 12 && buffer.slice(8, 12).toString() === 'WEBP';
  isValid = buffer.length > 2000 && (isJpeg || isPng || isWebp);
}

return { json: { ...scene, tavilyImageValid: isValid }, binary: $input.item.binary };

const photos = $json.photos || [];
const photo = photos[0];
const imageUrl = photo && photo.src && (photo.src.large2x || photo.src.large || photo.src.original);

const ctx = $('Check Tavily Images').first().json;
if (!imageUrl) {
  throw new Error('Pexels khong tra ve anh phu hop cho query: ' + (ctx.scene.stockQuery || ''));
}

return { json: { ...ctx, pexelsImageUrl: imageUrl } };

const ctx = $('Build Scene Subtitle Cues').first().json;
const imagePath = $json.fileName;
const staticData = $getWorkflowStaticData('global');
staticData.scenes = staticData.scenes || [];
staticData.scenes.push({
  ...ctx.scene,
  audioPath: ctx.audioPath,
  imagePath
});
return [{ json: { ...ctx, imagePath } }];

const fs = require('fs');
const path = require('path');
const staticData = $getWorkflowStaticData('global');
const scenes = (staticData.scenes || []).slice().sort((a, b) => a.sceneId - b.sceneId);
const ctx = $('Init Video Paths').first().json;

const storyboardPath = path.join(ctx.videoDir, 'storyboard.json');
fs.writeFileSync(storyboardPath, JSON.stringify({
  videoId: ctx.videoId,
  topic: ctx.topic,
  script: ctx.script,
  totalDuration: ctx.totalDuration,
  scenes
}, null, 2));

return [{ json: { ...ctx, storyboardPath, scenes } }];

// Builds an .ass file with 2 styles: base text + a 'Key' style used only for
// the highlighted keyword in each cue (bold, accent color, scale-pop-in),
// which is what gives the MrBeast-style 'pop on keyword' subtitle feel.
const fs = require('fs');
const path = require('path');
const ctx = $json;
const scenes = ctx.scenes;

function fmtTime(t) {
  const h = Math.floor(t / 3600);
  const m = Math.floor((t % 3600) / 60);
  const s = t % 60;
  return h + ':' + String(m).padStart(2, '0') + ':' + s.toFixed(2).padStart(5, '0');
}

const header = '[Script Info]\nScriptType: v4.00+\nPlayResX: 1080\nPlayResY: 1920\n\n' +
  '[V4+ Styles]\n' +
  'Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\n' +
  'Style: Base,Montserrat ExtraBold,64,&H00FFFFFF,&H00FFFFFF,&H00101010,&H80000000,1,0,1,3,2,2,60,60,260,1\n' +
  'Style: Key,Montserrat ExtraBold,64,&H0000E5FF,&H0000E5FF,&H00101010,&H80000000,1,0,1,3,2,2,60,60,260,1\n\n' +
  '[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n';

let offset = 0;
const lines = [];
for (const scene of scenes) {
  for (const cue of (scene.subtitleCues || [])) {
    const start = offset + cue.start;
    const end = offset + cue.end;
    // wrap to max 2 lines, highlight the keyword with a quick pop-in scale animation
    const words = cue.text.split(/\s+/);
    const mid = Math.ceil(words.length / 2);
    const line1 = words.slice(0, mid).join(' ');
    const line2 = words.slice(mid).join(' ');
    const highlight = (w) => w.toLowerCase() === String(cue.keyword).toLowerCase()
      ? '{\\t(0,120,\\fscx120\\fscy120)}{\\c&H00E5FF&}' + w + '{\\c&HFFFFFF&}{\\fscx100\\fscy100}'
      : w;
    const styled1 = line1.split(/\s+/).map(highlight).join(' ');
    const styled2 = line2.split(/\s+/).map(highlight).join(' ');
    const text = [styled1, styled2].filter(Boolean).join('\\N');
    lines.push('Dialogue: 0,' + fmtTime(start) + ',' + fmtTime(end) + ',Base,,0,0,0,,{\\fad(80,80)}' + text);
  }
  offset += scene.measuredDuration || scene.duration;
}

const assContent = header + lines.join('\n') + '\n';
const subtitlesPath = path.join(ctx.videoDir, 'subtitles.ass');
fs.writeFileSync(subtitlesPath, assContent);

return [{ json: { ...ctx, subtitlesPath } }];

// Generates a bash script that: (1) turns each scene's still image into a clip
// with scale+crop to fill the frame plus a Ken Burns zoompan (per the storyboard's
// camera_motion), synced to the real narration duration, (2) concatenates scenes
// with short crossfade (xfade) transitions, (3) mixes background music + sfx under
// the narration with sidechain ducking, (4) applies loudnorm, (5) burns in
// subtitles.ass, all at 1080x1920@30fps.
const path = require('path');
const ctx = $json;
const W = 1080, H = 1920, FPS = 30;
const dir = ctx.videoDir;
const scenes = ctx.scenes;
const bgm = path.join(ctx.BASE_DIR, 'assets', 'bgm', 'default.mp3');
const sfxWhoosh = path.join(ctx.BASE_DIR, 'assets', 'sfx', 'whoosh.wav');

function zoompan(camera, frames) {
  const base = `zoompan=d=${frames}:s=${W}x${H}:fps=${FPS}`;
  switch (camera) {
    case 'push-in': return `zoompan=z='min(1+0.18*on/${frames},1.18)':d=${frames}:x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':s=${W}x${H}:fps=${FPS}`;
    case 'pull-out': return `zoompan=z='max(1.18-0.18*on/${frames},1.0)':d=${frames}:x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':s=${W}x${H}:fps=${FPS}`;
    case 'pan-left': return `zoompan=z=1.12:d=${frames}:x='(iw-iw/zoom)*(1-on/${frames})':y='ih/2-(ih/zoom/2)':s=${W}x${H}:fps=${FPS}`;
    case 'pan-right': return `zoompan=z=1.12:d=${frames}:x='(iw-iw/zoom)*(on/${frames})':y='ih/2-(ih/zoom/2)':s=${W}x${H}:fps=${FPS}`;
    case 'slow-zoom':
    case 'parallax':
    case 'handheld-drift':
    case 'static':
    default: return `zoompan=z='min(zoom+0.0006,1.12)':d=${frames}:x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':s=${W}x${H}:fps=${FPS}`;
  }
}

let script = '#!/bin/bash\nset -e\ncd "' + dir + '"\nexec 2>> "' + dir + '/ffmpeg.log"\n\n';
const processed = [];
scenes.forEach((sc, i) => {
  const idx = String(sc.sceneId).padStart(2, '0');
  const dur = sc.measuredDuration || sc.duration;
  const frames = Math.round(dur * FPS);
  const img = 'scenes/scene_' + idx + '_image.jpg';
  const audio = 'scenes/scene_' + idx + '.wav';
  const out = 'scenes/scene_' + idx + '_final.mp4';
  processed.push(out);
  // still photo -> video: scale+crop to fill 1080x1920 (no bars), Ken Burns zoompan
  // sized to this scene's real narration duration, muxed with the narration audio at
  // a fixed 44100/stereo so concat never desyncs.
  script += 'ffmpeg -y -loop 1 -i "' + img + '" -i "' + audio + '" ' +
    '-filter_complex "[0:v]scale=' + W + ':' + H + ':force_original_aspect_ratio=increase,crop=' + W + ':' + H + ',setsar=1,' + zoompan(sc.camera_motion, frames) + ',format=yuv420p[v]" ' +
    '-map "[v]" -map 1:a -c:v libx264 -preset veryfast -crf 18 -r ' + FPS + ' ' +
    '-ar 44100 -ac 2 -c:a aac -t ' + dur.toFixed(2) + ' "' + out + '"\n';
});

// crossfade-concat all processed scenes (xfade + acrossfade), 0.35s transitions
const XF = 0.35;
let filterChain = '';
let vLabel = '0:v'; let aLabel = '0:a'; let acc = 0;
const inputs = processed.map(p => '-i "' + p + '"').join(' ');
processed.forEach((p, i) => {
  if (i === 0) return;
  const dur = (scenes[i - 1].measuredDuration || scenes[i - 1].duration);
  acc += dur - XF;
  const vOut = 'v' + i; const aOut = 'a' + i;
  filterChain += '[' + vLabel + '][' + i + ':v]xfade=transition=fade:duration=' + XF + ':offset=' + acc.toFixed(2) + '[' + vOut + '];';
  filterChain += '[' + aLabel + '][' + i + ':a]acrossfade=d=' + XF + '[' + aOut + '];';
  vLabel = vOut; aLabel = aOut;
});

const narrationMix = 'concat_video.mp4';
script += 'ffmpeg -y ' + inputs + ' -filter_complex "' + filterChain +
  '[' + vLabel + ']null[vout];[' + aLabel + ']anull[aout]" ' +
  '-map "[vout]" -map "[aout]" -c:v libx264 -preset veryfast -crf 18 -r ' + FPS + ' -c:a aac "' + narrationMix + '"\n';

// bgm + sfx under narration, ducked via sidechaincompress so music drops when voice speaks,
// then loudnorm for consistent platform loudness, then burn subtitles.ass
script += 'if [ -f "' + bgm + '" ]; then\n' +
  '  ffmpeg -y -i "' + narrationMix + '" -stream_loop -1 -i "' + bgm + '" -filter_complex "' +
  '[1:a]volume=0.18[bgm];[0:a][bgm]sidechaincompress=threshold=0.05:ratio=8:attack=5:release=300[bgmduck];' +
  '[0:a][bgmduck]amix=inputs=2:duration=first:dropout_transition=2,loudnorm=I=-14:TP=-1.5:LRA=11[aout]" ' +
  '-map 0:v -map "[aout]" -c:v copy -c:a aac mixed.mp4\n' +
  'else\n' +
  '  ffmpeg -y -i "' + narrationMix + '" -af loudnorm=I=-14:TP=-1.5:LRA=11 -c:v copy -c:a aac mixed.mp4\n' +
  'fi\n\n';

script += 'ffmpeg -y -i mixed.mp4 -vf "ass=subtitles.ass" -c:v libx264 -preset veryfast -crf 17 ' +
  '-c:a copy final_video.mp4\n';

const renderScriptPath = path.join(dir, 'render_video.sh');
require('fs').writeFileSync(renderScriptPath, script, { mode: 0o755 });

return [{ json: { ...ctx, renderScriptPath, finalVideoPath: path.join(dir, 'final_video.mp4') } }];

