function parseAgentJson(raw) {
  if (typeof raw !== 'string') return raw;
  let t = raw.trim();
  const fence = t.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fence) t = fence[1];
  if (!/^[\{\[]/.test(t.trim())) {
    const m = t.match(/\{[\s\S]*\}/);
    if (m) t = m[0];
  }
  return JSON.parse(t);
}

let seo;
try {
  seo = parseAgentJson($json.output);
} catch (e) {
  throw new Error('SEO Agent khong tra ve JSON hop le.');
}

const ctx = $('Build Render Script').first().json;
return [{ json: { ...ctx, seo } }];

