const entry = {
  videoId: ctx.videoId,
  topic: ctx.topic,
  publishedAt: new Date().toISOString(),
  finalVideoPath: ctx.finalVideoPath,
  youtubeVideoId: youtubeId,
  title: ctx.seo.title,
